import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"【Глава 2】 Подготовка","description":"","frontmatter":{},"headers":[],"relativePath":"ru/document/level-0/ch02-preparation.md","filePath":"ru/document/level-0/ch02-preparation.md","lastUpdated":1777787579000}`),a={name:`ru/document/level-0/ch02-preparation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="【глава-2】-подготовка" tabindex="-1">【Глава 2】 Подготовка <a class="header-anchor" href="#【глава-2】-подготовка" aria-label="Permalink to “【Глава 2】 Подготовка”">​</a></h1><p>Эта глава особенная, поскольку затрагивает финансовые операции. В соответствии с нейтральной позицией проекта, здесь не будет конкретных рекомендаций. Всё, что я могу сделать, — это рассказать, что вам понадобится.</p><h2 id="_2-1-приобретение-vps" tabindex="-1">2.1 Приобретение VPS <a class="header-anchor" href="#_2-1-приобретение-vps" aria-label="Permalink to “2.1 Приобретение VPS”">​</a></h2><p>Вам нужно получить работающий VPS с не заблокированным IP-адресом и выполнить следующие базовые действия в панели управления:</p><ol><li>Установить на VPS операционную систему Debian.</li><li>Записать IP-адрес VPS (в этой статье он будет обозначаться как <code>&quot;100.200.300.400&quot;</code>).<div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Это <strong>неверный</strong> IP-адрес, используемый только в качестве примера. Не забудьте заменить его на свой реальный IP-адрес.</p></div></li><li>Записать порт (Port) SSH для удалённого подключения к VPS.</li><li>Записать имя пользователя и пароль для удалённого подключения по SSH.</li></ol><p>Выбор и покупка VPS — дело непростое. Рекомендуем сначала изучить этот вопрос и выбрать тариф, который соответствует вашим финансовым возможностям и требованиям к скорости и качеству связи. Также можно воспользоваться бесплатными (постоянными или временными) предложениями от крупных облачных провайдеров, таких как Oracle Cloud и Google Cloud. Главное — не влезайте в долги.</p><div class="tip custom-block"><p class="custom-block-title">Пояснение</p><p>Несколько слов о выборе Debian в качестве операционной системы. Что бы вы ни слышали в интернете, какой бы дистрибутив Linux ни советовали вам гуру, все эти споры о том, какой Linux лучше, <strong>не имеют к вам никакого отношения</strong>! Последний стабильный выпуск Debian — это надёжная и стабильная операционная система, которая отлично подходит для работы VPN-сервера и достаточно оптимизирована (например, имеет специальное ядро для облачных сред и своевременную поддержку BBR). Когда вы освоитесь с Linux, можете попробовать и другие дистрибутивы.</p></div><h2 id="_2-2-выбор-доменного-имени" tabindex="-1">2.2 Выбор доменного имени <a class="header-anchor" href="#_2-2-выбор-доменного-имени" aria-label="Permalink to “2.2 Выбор доменного имени”">​</a></h2><p>Вам нужно получить доменное имя и добавить A-запись, указывающую на IP-адрес вашего VPS, в настройках DNS.</p><ol><li>Выберите надёжного международного регистратора доменных имён. Доменная зона (расширение домена) может быть любой, главное — не используйте <code>.cn</code>.</li><li>В настройках DNS добавьте A-запись, указывающую на IP-адрес вашего VPS (имя A-записи может быть любым, в этой статье оно будет обозначаться как <code>&quot;a-name&quot;</code>. Полное доменное имя будет выглядеть как <code>&quot;a-name.yourdomain.com&quot;</code>). Должно получиться примерно так:</li></ol><p><img src="/assets/ch02-img01-a-name.DXHjY1Jd.png" alt="Добавление A-записи" width="2084" height="440"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Это <strong>не</strong> настоящий URL-адрес. Не забудьте заменить его на свой реальный адрес.</p></div><h2 id="_2-3-необходимое-программное-обеспечение" tabindex="-1">2.3 Необходимое программное обеспечение <a class="header-anchor" href="#_2-3-необходимое-программное-обеспечение" aria-label="Permalink to “2.3 Необходимое программное обеспечение”">​</a></h2><ol><li><p>SSH-клиент для удалённого подключения:</p><ul><li>Windows: <a href="https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html" target="_blank" rel="noreferrer">PuTTY</a></li><li>macOS/Linux: Terminal</li></ul></li><li><p>Программа для передачи файлов:</p><ul><li>Windows: <a href="https://winscp.net/eng/index.php" target="_blank" rel="noreferrer">WinSCP</a></li><li>macOS/Linux: Terminal</li></ul></li><li><p>Хороший текстовый редактор:</p><ul><li>Windows/macOS/Linux: <a href="https://code.visualstudio.com" target="_blank" rel="noreferrer">VSCode</a></li></ul></li></ol><h2 id="_2-4-ваш-прогресс" tabindex="-1">2.4 Ваш прогресс <a class="header-anchor" href="#_2-4-ваш-прогресс" aria-label="Permalink to “2.4 Ваш прогресс”">​</a></h2><p>Если вы выполнили все пункты из этого раздела, у вас уже есть всё необходимое, чтобы открыть для себя новый мир. Так чего же мы ждём? Давайте перейдём к следующей главе и сделаем это!</p><blockquote><p>⬛⬛⬜⬜⬜⬜⬜⬜ 25%</p></blockquote>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};